/**
 * Main workflow — "Validate Row" Code node
 * ----------------------------------------------------------------------------
 * Input  : one item from the Google Sheets Trigger (one new Form response row).
 *          The row's keys are exactly the column headers from row 1 of the sheet.
 * Output : { ok: boolean, row: <original>, errors: string[] }
 *
 * Checks:
 *   1. Email is present and shaped like an email address.
 *   2. Name is present.
 *   3. Fulfillment Date is present and parseable.
 *   4. Fulfillment Type is "Pickup" or "Delivery".
 *   5. If Delivery, Delivery Address is non-empty.
 *   6. At least one SKU quantity column is > 0.
 *
 * IMPORTANT: This Code node does NOT hard-code the SKU column names.
 * Everything that is not in the META set below is treated as a candidate
 * SKU column. To add a menu item to the Form, you add a column to the sheet
 * AND a row to `item_config` — you do NOT edit this Code node.
 */
const row = $input.item.json;
const errors = [];

const email = String(row['Email'] ?? row['Email Address'] ?? '').trim();
if (!email) {
  errors.push('email is missing');
} else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
  errors.push('email format looks wrong');
}

const name = String(row['Name'] ?? '').trim();
if (!name) errors.push('name is missing');

const fulfillmentDate = String(row['Fulfillment Date'] ?? '').trim();
if (!fulfillmentDate) {
  errors.push('fulfillment date is missing');
} else if (Number.isNaN(Date.parse(fulfillmentDate))) {
  errors.push('fulfillment date is not a valid date');
}

const fulfillmentType = String(row['Fulfillment Type'] ?? '').trim();
if (!['Pickup', 'Delivery'].includes(fulfillmentType)) {
  errors.push('fulfillment type must be "Pickup" or "Delivery"');
}

const address = String(row['Delivery Address'] ?? '').trim();
if (fulfillmentType === 'Delivery' && !address) {
  errors.push('delivery address is required for Delivery orders');
}

// META = column headers we treat as customer / order metadata, NOT SKU quantities.
// Adding a new SKU column to the sheet does not require editing this set.
const META = new Set([
  'Timestamp',
  'Email', 'Email Address',
  'Name',
  'Contact Number', 'Phone',
  'Fulfillment Date',
  'Fulfillment Type',
  'Delivery Address',
  'Payment Method',
  'Special Instructions',
  'row_number',                    // injected by the Google Sheets Trigger
  'Invoice ID', 'Sync Status',     // write-back columns (round-tripped after sync)
]);

let totalQty = 0;
for (const [k, v] of Object.entries(row)) {
  if (META.has(k)) continue;
  const n = Number(v);
  if (Number.isFinite(n) && n > 0) totalQty += n;
}
if (totalQty <= 0) errors.push('no item quantities greater than zero');

return [{ json: { ok: errors.length === 0, row, errors } }];

/**
 * Main workflow — "Normalize Order" Code node
 * ----------------------------------------------------------------------------
 * Converts the validated sheet row into the NORMALIZED ORDER payload that
 * the "Order → Invoice" sub-workflow accepts. This is the boundary contract
 * shared between the Google Sheet intake (today) and the future Supabase
 * form intake — both produce this same shape.
 *
 * Normalized order shape:
 * {
 *   source: 'google_sheet' | 'supabase_form',
 *   source_row_id: '<source-prefix>:<stable-id>',
 *   customer: { email, name, phone },
 *   fulfillment: { date, type, address },
 *   payment_method, special_instructions,
 *   item_quantities: { '<sheet_column_header>': <number> },
 *   writeback: { kind, ...intake-specific }
 * }
 */
const crypto = require('crypto');
const row = $input.item.json.row;

const email = String(row['Email'] ?? row['Email Address'] ?? '').trim().toLowerCase();
const timestamp = String(row['Timestamp'] ?? '').trim();

// Stable id: hash of (timestamp + email). Survives row reorders / re-runs.
const idHash = crypto
  .createHash('sha256')
  .update(timestamp + '|' + email)
  .digest('hex')
  .slice(0, 16);

const META = new Set([
  'Timestamp',
  'Email', 'Email Address',
  'Name',
  'Contact Number', 'Phone',
  'Fulfillment Date',
  'Fulfillment Type',
  'Delivery Address',
  'Payment Method',
  'Special Instructions',
  'row_number',
  'Invoice ID', 'Sync Status',
]);

const item_quantities = {};
for (const [k, v] of Object.entries(row)) {
  if (META.has(k)) continue;
  const n = Number(v);
  if (Number.isFinite(n) && n > 0) item_quantities[k] = n;
}

const address = String(row['Delivery Address'] ?? '').trim();

const payload = {
  source: 'google_sheet',
  source_row_id: `gs:${idHash}`,
  customer: {
    email,
    name: String(row['Name'] ?? '').trim(),
    phone: String(row['Contact Number'] ?? row['Phone'] ?? '').trim(),
  },
  fulfillment: {
    date: String(row['Fulfillment Date'] ?? '').trim(),
    type: String(row['Fulfillment Type'] ?? '').trim(),
    address: address || null,
  },
  payment_method: String(row['Payment Method'] ?? '').trim(),
  special_instructions: String(row['Special Instructions'] ?? '').trim(),
  item_quantities,
  writeback: {
    kind: 'google_sheet',
    spreadsheet_id: $env.GS_SPREADSHEET_ID,
    sheet_name: $env.GS_RESPONSES_SHEET,
    row_number: row.row_number ?? null,
  },
};

return [{ json: payload }];

/**
 * Main workflow — "Build Notify Payload" Code node (validation-failure path)
 * ----------------------------------------------------------------------------
 * When "Validate Row" finds problems, we hand the Notify sub-workflow a
 * compact, channel-agnostic payload. The Notify workflow decides whether
 * to format it as Slack text or email body.
 */
const v = $input.item.json;
return [{
  json: {
    severity: 'error',
    stage: 'sheet-intake-validation',
    source: 'google_sheet',
    errors: v.errors || ['unknown validation failure'],
    row: v.row,
  },
}];

/**
 * Sub-workflow — "Validate Payload" Code node
 * ----------------------------------------------------------------------------
 * Defensive shape-check on the normalized order payload received from any
 * caller (the Google Sheet intake today, the Supabase intake later).
 *
 * On any missing required field, we THROW — n8n's "Error Workflow" setting
 * on this workflow routes that to the Notify sub-workflow.
 */
const p = $input.item.json;
const errors = [];

if (!p || typeof p !== 'object') errors.push('payload is missing');
if (!p?.source) errors.push('source is missing');
if (!p?.source_row_id) errors.push('source_row_id is missing');
if (!p?.customer?.email && !p?.customer?.phone) {
  errors.push('need at least email or phone for contact dedupe');
}
if (!p?.customer?.name) errors.push('customer name is missing');
if (!p?.item_quantities || Object.keys(p.item_quantities).length === 0) {
  errors.push('no item quantities supplied');
}

if (errors.length) {
  throw new Error('Invalid order payload: ' + errors.join('; '));
}

return [{ json: p }];

/**
 * Sub-workflow — "Exit Idempotent" Code node
 * ----------------------------------------------------------------------------
 * Reached when the existing-invoice GET returns a hit for this
 * source_row_id. We do NOT create anything; we just return a summary
 * pointing at the already-created invoice.
 */
const order = $('Validate Payload').item.json;
const existing = $('Check Existing Invoice').item.json.invoices?.[0] ?? null;

return [{
  json: {
    ok: true,
    idempotent: true,
    source: order.source,
    source_row_id: order.source_row_id,
    invoice_id: existing?.invoice_id ?? null,
    invoice_status: existing?.status ?? null,
    invoice_number: existing?.invoice_number ?? null,
    message: 'order already invoiced — skipped',
  },
}];

/**
 * Sub-workflow — "Build Create-Contact Body" Code node
 * ----------------------------------------------------------------------------
 * Runs only when both the email and phone lookups failed. Builds the body
 * for POST /contacts.
 */
const order = $('Validate Payload').item.json;
const c = order.customer;

return [{
  json: {
    contact_name: c.name,
    contact_type: 'customer',
    contact_persons: [{
      first_name: c.name,
      email: c.email || undefined,
      phone: c.phone || undefined,
      is_primary_contact: true,
    }],
  },
}];

/**
 * Sub-workflow — "Resolve Contact" Code node
 * ----------------------------------------------------------------------------
 * Reads the outputs of the three preceding contact-resolution HTTP nodes
 * (Find by Email → Find by Phone → Create) and picks the contact_id from
 * whichever path succeeded. Only one of the three branches will have run
 * for any single execution; the others will be undefined.
 *
 * Output is the normalized order plus `contact_id` and `contact_lookup`
 * ("matched_email" | "matched_phone" | "created"), passed forward.
 */
const order = $('Validate Payload').item.json;

let contact_id = null;
let lookup = null;

// Email-match branch
try {
  const out = $('Find Contact by Email').item?.json;
  if (out?.contacts?.length > 0) {
    contact_id = out.contacts[0].contact_id;
    lookup = 'matched_email';
  }
} catch (_) { /* branch didn't run */ }

// Phone-match branch
if (!contact_id) {
  try {
    const out = $('Find Contact by Phone').item?.json;
    if (out?.contacts?.length > 0) {
      contact_id = out.contacts[0].contact_id;
      lookup = 'matched_phone';
    }
  } catch (_) { /* branch didn't run */ }
}

// Create branch
if (!contact_id) {
  try {
    const out = $('Create Contact').item?.json;
    contact_id = out?.contact?.contact_id || null;
    if (contact_id) lookup = 'created';
  } catch (_) { /* branch didn't run */ }
}

if (!contact_id) {
  throw new Error('Could not resolve a Zoho contact_id (no match and no create result).');
}

return [{ json: { ...order, contact_id, contact_lookup: lookup } }];

/**
 * Sub-workflow — "Build Line Items" Code node
 * ----------------------------------------------------------------------------
 * Joins the order's qty map against the `item_config` table to produce Zoho
 * line_items[]. Two cases:
 *
 *   - Config row has a non-empty `zoho_item_id`:
 *       → catalogued line: { item_id, quantity }
 *
 *   - Config row exists but `zoho_item_id` is blank
 *     (or no config row at all for that column):
 *       → ad-hoc line: { name, rate, quantity, description }
 *       → review flag appended so notes show "[REVIEW: uncatalogued item ...]"
 *
 * `item_config` columns (single source of truth — edit the sheet, not this code):
 *   sheet_column_header | zoho_item_id | item_name | active | default_rate
 *
 * `default_rate` is an OPTIONAL convenience column used only for the
 * uncatalogued / ad-hoc case so the draft has a non-zero starting price.
 * Leave it blank and you'll get rate=0 (still safe — it's a draft).
 */
const order = $('Resolve Contact').item.json;
const cfgRows = $('Load item_config').all().map(i => i.json);

const active = cfgRows.filter(r =>
  String(r.active ?? '').trim().toLowerCase() === 'true'
);
const byHeader = new Map(
  active.map(r => [String(r.sheet_column_header ?? '').trim(), r])
);

const line_items = [];
const review = [];

for (const [header, rawQty] of Object.entries(order.item_quantities)) {
  const qty = Number(rawQty);
  if (!Number.isFinite(qty) || qty <= 0) continue;

  const row = byHeader.get(header);

  if (!row) {
    // Sheet column with no item_config row at all.
    review.push(`no item_config row for column "${header}" (qty ${qty})`);
    line_items.push({
      name: header,
      rate: 0,
      quantity: qty,
      description: 'AD-HOC: no item_config row matched this column header',
    });
    continue;
  }

  const zohoItemId = String(row.zoho_item_id ?? '').trim();
  if (zohoItemId) {
    line_items.push({ item_id: zohoItemId, quantity: qty });
  } else {
    const itemName = String(row.item_name ?? header).trim();
    const rate = Number(row.default_rate ?? 0) || 0;
    review.push(`uncatalogued item "${itemName}" (qty ${qty}) — zoho_item_id is blank in item_config`);
    line_items.push({
      name: itemName,
      rate,
      quantity: qty,
      description: 'AD-HOC: zoho_item_id blank in item_config',
    });
  }
}

if (line_items.length === 0) {
  throw new Error('No line items produced — check item_config or the row qty columns.');
}

return [{ json: { ...order, line_items, review } }];

/**
 * Sub-workflow — "Build Invoice Payload" Code node
 * ----------------------------------------------------------------------------
 * Assembles the full Zoho Invoice create-request body from the contact id,
 * line items, and custom fields.
 *
 * Zoho custom fields are referenced by `label` here. The labels MUST match
 * what you create in:
 *   Zoho Invoice → Settings → Custom Fields → Invoices
 *
 *   Label                    Data type
 *   ----------------------   -------------
 *   cf_source_row_id         Single line
 *   cf_fulfillment_date      Date
 *   cf_fulfillment_type      Dropdown (Pickup, Delivery)
 *   cf_payment_method        Single line
 *
 * Invoice date = today (creation date). Fulfillment date is a custom field,
 * NOT the invoice date, per spec.
 */
const order = $('Build Line Items').item.json;

// Notes: combine the customer's special instructions with any uncatalogued
// item review flags so the draft is loud about anything needing attention.
const notes = [
  order.special_instructions || '',
  ...(order.review || []).map(r => `[REVIEW: uncatalogued item — ${r}]`),
]
  .filter(Boolean)
  .join('\n')
  .trim();

const payload = {
  customer_id: order.contact_id,
  date: new Date().toISOString().slice(0, 10),
  line_items: order.line_items,
  notes,
  custom_fields: [
    { label: 'cf_source_row_id',    value: order.source_row_id },
    { label: 'cf_fulfillment_date', value: order.fulfillment.date },
    { label: 'cf_fulfillment_type', value: order.fulfillment.type },
    { label: 'cf_payment_method',   value: order.payment_method },
  ],
};

if (order.fulfillment.address) {
  payload.shipping_address = { address: order.fulfillment.address };
}

return [{ json: { ...order, invoice_payload: payload } }];

/**
 * Sub-workflow — "Return Summary" Code node
 * ----------------------------------------------------------------------------
 * Final node. Returns a small JSON summary to the calling workflow so the
 * intake can log or display it. Keep this lean — secrets must NEVER leak
 * back into the caller's context.
 */
const order = $('Build Invoice Payload').item.json;
const invoice = $('Create Draft Invoice')?.item?.json?.invoice ?? null;

return [{
  json: {
    ok: true,
    idempotent: false,
    source: order.source,
    source_row_id: order.source_row_id,
    contact_id: order.contact_id,
    contact_lookup: order.contact_lookup,
    invoice_id: invoice?.invoice_id ?? null,
    invoice_status: invoice?.status ?? 'draft',
    invoice_number: invoice?.invoice_number ?? null,
    review_flags: order.review ?? [],
  },
}];

/**
 * Notify sub-workflow — "Format Message" Code node
 * ----------------------------------------------------------------------------
 * Formats the incoming payload into a single human-readable message used
 * by both Slack and email channels.
 */
const p = $input.item.json;
const lines = [];

lines.push(`*Bagnetchon automation alert*`);
lines.push(`severity: ${p.severity ?? 'info'}`);
lines.push(`stage:    ${p.stage ?? 'unknown'}`);
lines.push(`source:   ${p.source ?? 'unknown'}`);

if (Array.isArray(p.errors) && p.errors.length) {
  lines.push('');
  lines.push('errors:');
  for (const e of p.errors) lines.push(`  - ${e}`);
}

if (p.row && typeof p.row === 'object') {
  lines.push('');
  lines.push('row:');
  for (const [k, v] of Object.entries(p.row)) {
    lines.push(`  ${k}: ${typeof v === 'object' ? JSON.stringify(v) : v}`);
  }
}

if (p.error_message) {
  lines.push('');
  lines.push(`error: ${p.error_message}`);
}

const text = lines.join('\n');
const subject = `[Bagnetchon] ${p.severity ?? 'info'} at ${p.stage ?? 'unknown'}`;

return [{ json: { text, subject } }];
